import type { OpenapiToolNamesOptions } from "apps/openapi";
import gmail from "./gmail-openapi.json" with { type: "json" };

// The inferred JSON type has no index signature, so widen it once here.
const document: JsonObject = JSON.parse(JSON.stringify(gmail));

// Every operation in the generated document already carries a plain bearer requirement.
export const options = {
  source: { document },
  allowedOrigin: "https://gmail.googleapis.com",
  securitySchemes: { bearer: { type: "http", scheme: "bearer" } },
  methods: {
    oauth: [{ scheme: "bearer", field: "access_token", part: "value", prefix: "" }],
  },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/gmail",
  "description": "Read, search, send and organize Gmail messages, threads, drafts, labels, filters and settings through the Gmail API.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "Gmail"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.16"
  }
}

// Runs the generated Gmail tools, in this package and in the all-in-one `google` package, through
// the apps host against a recording fake Google, and checks each request against Gmail's documented
// formats. Messages, ids and tokens are synthetic. Run with `bun test packages/gmail`.
import assert from "node:assert/strict";
import { after, before, describe, test } from "node:test";
import { accountId, hostPackage, token, type Host, type Recorded } from "../../scripts/fake-google.ts";

const mime = (headers: Record<string, string>, text: string) =>
  [...Object.entries(headers).map(([name, value]) => `${name}: ${value}`), "Content-Type: text/plain; charset=UTF-8", "", text].join("\r\n");
const message = mime(
  { From: "sender@example.com", To: "recipient@example.com", Subject: "Synthetic test", "Message-ID": "<original-1@example.com>" },
  "Hello from a test. Café ✓",
);
const reply = mime(
  {
    From: "sender@example.com",
    To: "recipient@example.com",
    Subject: "Re: Synthetic test",
    "In-Reply-To": "<original-1@example.com>",
    References: "<original-1@example.com>",
  },
  "A synthetic reply.",
);
const raw = Buffer.from(message).toString("base64url");
const replyRaw = Buffer.from(reply).toString("base64url");
const me = { userId: "me" };
const credentialParameters = ["access_token", "oauth_token", "key"];

/** The JSON operations that take a whole message, and the request Gmail documents for each. */
const jsonCases = [
  { name: "messages.send", tool: "gmailUsersMessagesSend", path: me, body: { raw }, method: "POST", url: "/gmail/v1/users/me/messages/send" },
  {
    name: "messages.send as a reply",
    tool: "gmailUsersMessagesSend",
    path: me,
    body: { raw: replyRaw, threadId: "thread-1" },
    method: "POST",
    url: "/gmail/v1/users/me/messages/send",
  },
  {
    name: "drafts.create",
    tool: "gmailUsersDraftsCreate",
    path: me,
    body: { message: { raw: replyRaw, threadId: "thread-1" } },
    method: "POST",
    url: "/gmail/v1/users/me/drafts",
  },
  { name: "drafts.update", tool: "gmailUsersDraftsUpdate", path: { ...me, id: "draft-1" }, body: { message: { raw } }, method: "PUT", url: "/gmail/v1/users/me/drafts/draft-1" },
  { name: "drafts.send", tool: "gmailUsersDraftsSend", path: me, body: { id: "draft-1" }, method: "POST", url: "/gmail/v1/users/me/drafts/send" },
  { name: "messages.insert", tool: "gmailUsersMessagesInsert", path: me, body: { raw }, method: "POST", url: "/gmail/v1/users/me/messages" },
  { name: "messages.import", tool: "gmailUsersMessagesImport", path: me, body: { raw }, method: "POST", url: "/gmail/v1/users/me/messages/import" },
] as const;

/** The upload operations: a simple upload of the RFC 822 message to Gmail's /upload path. */
const mediaCases = [
  { tool: "gmailUsersMessagesSendMedia", path: me, method: "POST", url: "/upload/gmail/v1/users/me/messages/send" },
  { tool: "gmailUsersMessagesInsertMedia", path: me, method: "POST", url: "/upload/gmail/v1/users/me/messages" },
  { tool: "gmailUsersMessagesImportMedia", path: me, method: "POST", url: "/upload/gmail/v1/users/me/messages/import" },
  { tool: "gmailUsersDraftsCreateMedia", path: me, method: "POST", url: "/upload/gmail/v1/users/me/drafts" },
  { tool: "gmailUsersDraftsUpdateMedia", path: { ...me, id: "draft-1" }, method: "PUT", url: "/upload/gmail/v1/users/me/drafts/draft-1" },
] as const;

/**
 * Calls a write twice: first without approval, which must stop before any request reaches Google,
 * then with the user's approval. Returns the one request the approved call sent.
 */
const approvedCall = async (host: Host, tool: string, input: unknown): Promise<Recorded> => {
  const sent = host.requests.length;
  const unapproved = await host.call(tool, input);
  assert.equal(unapproved.ok ? "ok" : unapproved.error._tag, "HostToolApprovalRequired", `${tool} ran without approval`);
  assert.equal(host.requests.length, sent, `${tool} reached Google before approval`);
  const approved = await host.call(tool, input, { approve: true });
  assert.ok(approved.ok, `${tool} failed: ${JSON.stringify(approved)}`);
  assert.equal(host.requests.length, sent + 1, `${tool} should send exactly one request`);
  const request = host.requests.at(-1)!;
  assert.equal(request.host, "gmail.googleapis.com");
  assert.equal(request.authorization, `Bearer ${token}`);
  return request;
};

/** The same Gmail API, standalone and as `api.gmail` in the all-in-one package. */
for (const mount of [
  { pkg: "gmail", prefix: "api.users." },
  { pkg: "google", prefix: "api.gmail.users." },
]) {
  describe(`${mount.pkg}: generated Gmail tools`, () => {
    let host: Host;
    before(async () => {
      host = await hostPackage(mount.pkg);
      host.answer(() => ({ id: "result-1" }));
    });
    after(() => host.close());

    for (const c of jsonCases) {
      test(`${c.name} asks first, then sends JSON to ${c.method} ${c.url}`, async () => {
        const input = { accountId, input: { path: c.path, contentType: "application/json", body: c.body } };
        const request = await approvedCall(host, mount.prefix + c.tool, input);
        assert.equal(request.method, c.method);
        assert.equal(request.path, c.url);
        assert.equal([...request.query].length, 0);
        assert.match(request.contentType ?? "", /^application\/json\b/);
        assert.deepEqual(JSON.parse(request.body.toString("utf8")), c.body);
      });
    }

    test("a reply's raw message carries the thread's subject and references", async () => {
      const input = { accountId, input: { path: me, contentType: "application/json", body: { raw: replyRaw, threadId: "thread-1" } } };
      const sent = JSON.parse((await approvedCall(host, `${mount.prefix}gmailUsersMessagesSend`, input)).body.toString("utf8"));
      assert.equal(sent.threadId, "thread-1");
      const headers = Buffer.from(sent.raw, "base64url").toString("utf8").split("\r\n\r\n")[0]!;
      assert.match(headers, /^Subject: Re: Synthetic test$/m);
      assert.match(headers, /^In-Reply-To: <original-1@example\.com>$/m);
      assert.match(headers, /^References: <original-1@example\.com>$/m);
    });

    for (const c of mediaCases) {
      test(`${c.tool} asks first, then uploads the message's bytes to ${c.method} ${c.url}`, async () => {
        const input = {
          accountId,
          input: { path: c.path, query: { uploadType: "media" }, contentType: "message/rfc822", body: Buffer.from(message).toString("base64") },
        };
        const request = await approvedCall(host, mount.prefix + c.tool, input);
        assert.equal(request.method, c.method);
        assert.equal(request.path, c.url);
        assert.equal(request.query.get("uploadType"), "media");
        assert.equal(request.contentType, "message/rfc822");
        assert.deepEqual(request.body, Buffer.from(message));
      });
    }

    test("drafts.send has no upload tool, because an upload cannot name the draft", async () => {
      const names = new Set((await host.tools()).map((tool) => tool.name));
      const media = [...names].filter((name) => name.startsWith(mount.prefix) && name.endsWith("Media")).sort();
      assert.deepEqual(media, mediaCases.map((c) => mount.prefix + c.tool).sort());
      assert.ok(names.has(`${mount.prefix}gmailUsersDraftsSend`));
    });

    test("Google's standard query parameters, such as quotaUser, are accepted and forwarded", async () => {
      const list = await host.call(`${mount.prefix}gmailUsersMessagesList`, {
        accountId,
        input: { path: me, query: { q: "is:unread", quotaUser: "quota-user-1", fields: "messages(id)", prettyPrint: false } },
      });
      assert.ok(list.ok, JSON.stringify(list));
      const listed = host.requests.at(-1)!;
      assert.equal(listed.method, "GET");
      assert.equal(listed.path, "/gmail/v1/users/me/messages");
      assert.equal(listed.query.get("quotaUser"), "quota-user-1");
      assert.equal(listed.query.get("fields"), "messages(id)");
      assert.equal(listed.query.get("prettyPrint"), "false");
    });

    test("uploads accept Google's standard query parameters too", async () => {
      const upload = await approvedCall(host, `${mount.prefix}gmailUsersMessagesSendMedia`, {
        accountId,
        input: { path: me, query: { uploadType: "media", quotaUser: "quota-user-1" }, contentType: "message/rfc822", body: Buffer.from(message).toString("base64") },
      });
      assert.equal(upload.query.get("uploadType"), "media");
      assert.equal(upload.query.get("quotaUser"), "quota-user-1");
    });

    test("an upload accepts only a simple upload", async () => {
      const result = await host.call(`${mount.prefix}gmailUsersMessagesSendMedia`, {
        accountId,
        input: { path: me, query: { uploadType: "resumable" }, contentType: "message/rfc822", body: Buffer.from(message).toString("base64") },
      });
      assert.equal(result.ok ? "ok" : result.error._tag, "HostInputInvalid");
    });

    test("a write whose body Gmail treats as optional can still omit it", async () => {
      const request = await approvedCall(host, `${mount.prefix}gmailUsersLabelsPatch`, { accountId, input: { path: { ...me, id: "Label_1" } } });
      assert.equal(request.method, "PATCH");
      assert.equal(request.path, "/gmail/v1/users/me/labels/Label_1");
      assert.equal(request.body.length, 0);
    });

    // A credential given as a tool argument would land in the request URL and the approval prompt;
    // the account binding supplies credentials, so these standard parameters are not offered.
    test("credential query parameters are refused and never reach a request URL", async () => {
      for (const name of credentialParameters) {
        const sent = host.requests.length;
        const listed = await host.call(`${mount.prefix}gmailUsersMessagesList`, { accountId, input: { path: me, query: { [name]: "synthetic-credential" } } });
        assert.equal(listed.ok ? "ok" : listed.error._tag, "HostInputInvalid", name);
        const upload = await host.call(`${mount.prefix}gmailUsersMessagesSendMedia`, {
          accountId,
          input: { path: me, query: { uploadType: "media", [name]: "synthetic-credential" }, contentType: "message/rfc822", body: Buffer.from(message).toString("base64") },
        });
        assert.equal(upload.ok ? "ok" : upload.error._tag, "HostInputInvalid", name);
        assert.equal(host.requests.length, sent, `${name} reached Google`);
      }
      for (const request of host.requests) for (const name of credentialParameters) assert.equal(request.query.has(name), false, `${name} in ${request.path}`);
    });
  });
}

// Generated by scripts/google-vendor.ts from shared/google-tools; edit the original and rerun it.
// Basalt's catalog carries edits to this copy (src/catalog/*.patch); re-vendoring must keep them.
// Gmail tools shaped for agents: search returns readable thread summaries across every linked
// account, reads return decoded text, and writes take plain fields instead of raw MIME.
import { array, boolean, mutation, number, object, query, string, type MutationContext, type QueryContext } from "apps";
import { always } from "apps/operations/approval";
import { Attachments, attachmentsHelp, deliver, encodeMessage, resolveAttachments, type AttachmentInput } from "./mime.js";
import { scheduleDraft, scheduleTools, sendTime } from "./schedule.js";
import {
  decodeBody,
  encodeHeader,
  fanOut,
  google,
  htmlToText,
  mapLimit,
  select,
  single,
  type Base,
  type Source,
  type Target,
} from "./shared.js";

const base = "https://gmail.googleapis.com/gmail/v1/users/me";
const account = string().optional();

interface Part {
  readonly mimeType?: string;
  readonly filename?: string;
  readonly headers?: readonly { readonly name: string; readonly value: string }[];
  readonly body?: { readonly data?: string; readonly size?: number; readonly attachmentId?: string };
  readonly parts?: readonly Part[];
}
interface Message {
  readonly id: string;
  readonly threadId: string;
  readonly labelIds?: readonly string[];
  readonly snippet?: string;
  readonly internalDate?: string;
  readonly payload?: Part;
}

const header = (part: Part | undefined, name: string) =>
  part?.headers?.find((h) => h.name.toLowerCase() === name.toLowerCase())?.value;

const charset = (part: Part) => /charset="?([^";]+)"?/i.exec(header(part, "Content-Type") ?? "")?.[1];

/** The message text: its text/plain part, else its HTML part as text. Attachments are listed, not read. */
const content = (payload: Part | undefined) => {
  let plain: string | undefined;
  let html: string | undefined;
  const attachments: { filename: string; mimeType: string; size: number; attachmentId: string }[] = [];
  const walk = (part: Part) => {
    if (part.filename && part.body?.attachmentId) {
      attachments.push({
        filename: part.filename,
        mimeType: part.mimeType ?? "application/octet-stream",
        size: part.body.size ?? 0,
        attachmentId: part.body.attachmentId,
      });
      return;
    }
    if (part.body?.data && part.mimeType === "text/plain" && plain === undefined) plain = decodeBody(part.body.data, charset(part));
    if (part.body?.data && part.mimeType === "text/html" && html === undefined) html = decodeBody(part.body.data, charset(part));
    for (const child of part.parts ?? []) walk(child);
  };
  if (payload) walk(payload);
  return { body: (plain ?? (html === undefined ? "" : htmlToText(html))).trim(), attachments };
};

/** Label IDs to names; system labels keep their IDs (INBOX, UNREAD, STARRED...). */
const labelNames = async (ctx: Base, target: Target) => {
  const { labels = [] } = await google(ctx, target, `${base}/labels`);
  return new Map<string, string>((labels as { id: string; name: string }[]).map((label) => [label.id, label.name]));
};

const summary = (target: Target, message: Message, names: Map<string, string>) => ({
  account: target.email,
  messageId: message.id,
  threadId: message.threadId,
  from: header(message.payload, "From") ?? "",
  to: header(message.payload, "To") ?? "",
  subject: header(message.payload, "Subject") ?? "",
  date: message.internalDate ? new Date(Number(message.internalDate)).toISOString() : "",
  snippet: message.snippet ?? "",
  unread: message.labelIds?.includes("UNREAD") ?? false,
  labels: (message.labelIds ?? []).filter((id) => id !== "UNREAD").map((id) => names.get(id) ?? id),
});

const full = (target: Target, message: Message, names: Map<string, string>) => ({
  ...summary(target, message, names),
  cc: header(message.payload, "Cc") ?? "",
  replyTo: header(message.payload, "Reply-To") ?? "",
  ...content(message.payload),
});

/** Resolves label names or IDs, case-insensitively, to IDs. */
const labelIds = (names: Map<string, string>, wanted: readonly string[]) => {
  const byName = new Map([...names].map(([id, name]) => [name.toLowerCase(), id]));
  return wanted.map((label) => {
    const id = names.has(label) ? label : byName.get(label.toLowerCase());
    if (id === undefined) throw new Error(`No Gmail label named ${label}. Create it first, or list labels with gmail.labels.`);
    return id;
  });
};

const Compose = {
  account,
  to: array(string()).optional(),
  cc: array(string()).optional(),
  bcc: array(string()).optional(),
  subject: string().optional(),
  body: string(),
  html: boolean().optional(),
  replyToMessageId: string().optional(),
  replyAll: boolean().optional(),
  from: string().optional(),
  attachments: Attachments,
};
type ComposeInput = {
  readonly account?: string;
  readonly to?: readonly string[];
  readonly cc?: readonly string[];
  readonly bcc?: readonly string[];
  readonly subject?: string;
  readonly body: string;
  readonly html?: boolean;
  readonly replyToMessageId?: string;
  readonly replyAll?: boolean;
  readonly from?: string;
  readonly attachments?: readonly AttachmentInput[];
};

const addresses = (value: string | undefined) =>
  (value ?? "")
    .split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/)
    .map((item) => item.trim())
    .filter(Boolean);
const bare = (address: string) => (/<([^>]+)>/.exec(address)?.[1] ?? address).trim().toLowerCase();

/**
 * Builds the RFC 2822 message with its attachments. A reply takes the original's thread, subject
 * and references, and addresses its sender (and, with replyAll, everyone else on it except this account).
 */
const compose = async (ctx: Base, target: Target, input: ComposeInput) => {
  let to = [...(input.to ?? [])];
  let cc = [...(input.cc ?? [])];
  let subject = input.subject;
  let threadId: string | undefined;
  const extra: string[] = [];
  if (input.replyToMessageId) {
    const original: Message = await google(ctx, target, `${base}/messages/${encodeURIComponent(input.replyToMessageId)}`, {
      search: { format: "metadata", metadataHeaders: ["From", "To", "Cc", "Subject", "Message-ID", "References", "Reply-To"] },
    });
    threadId = original.threadId;
    const messageId = header(original.payload, "Message-ID");
    if (messageId) {
      extra.push(`In-Reply-To: ${messageId}`);
      extra.push(`References: ${[header(original.payload, "References"), messageId].filter(Boolean).join(" ")}`);
    }
    const originalSubject = header(original.payload, "Subject") ?? "";
    subject ??= /^re:/i.test(originalSubject) ? originalSubject : `Re: ${originalSubject}`;
    const self = target.email.toLowerCase();
    const sender = header(original.payload, "Reply-To") ?? header(original.payload, "From") ?? "";
    // Replying to your own message goes back to its recipients.
    const fromSelf = bare(header(original.payload, "From") ?? "") === self;
    if (to.length === 0) to = fromSelf ? addresses(header(original.payload, "To")) : addresses(sender);
    if (input.replyAll) {
      const already = new Set([...to, ...cc].map(bare));
      for (const address of [...addresses(header(original.payload, "To")), ...addresses(header(original.payload, "Cc"))]) {
        if (bare(address) === self || already.has(bare(address))) continue;
        already.add(bare(address));
        cc.push(address);
      }
    }
  }
  const headers = [
    ...(input.from ? [`From: ${input.from}`] : []),
    ...(to.length ? [`To: ${to.join(", ")}`] : []),
    ...(cc.length ? [`Cc: ${cc.join(", ")}`] : []),
    ...(input.bcc?.length ? [`Bcc: ${input.bcc.join(", ")}`] : []),
    `Subject: ${encodeHeader(subject ?? "")}`,
    ...extra,
  ];
  const files = await resolveAttachments(ctx, target, input.attachments);
  const message = encodeMessage(headers, input.body, input.html ?? false, files);
  return { message, threadId, to, cc, subject: subject ?? "", attachments: files.map((file) => file.filename) };
};

/** Matching threads across targets, newest first, each summarised by its latest message. */
export const searchMail = async (ctx: Base, targets: readonly Target[], q: string, max: number) => {
  const { items, errors } = await fanOut(targets, async (target) => {
    const [{ threads = [] }, names] = await Promise.all([
      google(ctx, target, `${base}/threads`, { search: { q, maxResults: max } }),
      labelNames(ctx, target),
    ]);
    return mapLimit(threads as { id: string }[], 10, async ({ id }) => {
      const thread: { messages?: Message[] } = await google(ctx, target, `${base}/threads/${id}`, {
        search: { format: "metadata", metadataHeaders: ["From", "To", "Subject", "Date"] },
      });
      const messages = thread.messages ?? [];
      const latest = messages.at(-1)!;
      return {
        ...summary(target, latest, names),
        messageCount: messages.length,
        unread: messages.some((message) => message.labelIds?.includes("UNREAD")),
      };
    });
  });
  items.sort((a, b) => b.date.localeCompare(a.date));
  return { threads: items.slice(0, max), errors };
};

/** The curated tools and their router's metadata; `source` names the package's accounts. */
export const gmail = (source: Source) => ({
  tools: {
    search: query(
      {
        description:
          "Search mail with Gmail search syntax (from:, to:, subject:, is:unread, has:attachment, newer_than:7d, label:, in:inbox...) across every linked Google account, or one. Returns matching threads, newest first, each with its latest message's sender, subject, date and snippet. Read one with readThread.",
        input: object({
          query: string(),
          account,
          max: number().optional(),
        }),
      },
      async (ctx: QueryContext, input) =>
        searchMail(ctx, await select(ctx, source, input.account), input.query, Math.min(Math.max(input.max ?? 20, 1), 100)),
    ),
    readThread: query(
      {
        description: "Read a whole thread as decoded text: every message's headers, body and attachment list, oldest first.",
        input: object({ account, threadId: string({ minLength: 1 }) }),
      },
      async (ctx: QueryContext, input) => {
        const target = await single(ctx, source, input.account);
        const [thread, names] = await Promise.all([
          google(ctx, target, `${base}/threads/${encodeURIComponent(input.threadId)}`, { search: { format: "full" } }),
          labelNames(ctx, target),
        ]);
        return { account: target.email, threadId: input.threadId, messages: ((thread.messages ?? []) as Message[]).map((m) => full(target, m, names)) };
      },
    ),
    readMessage: query(
      {
        description: "Read one message as decoded text: headers, body (HTML converted to text) and attachment list.",
        input: object({ account, messageId: string({ minLength: 1 }) }),
      },
      async (ctx: QueryContext, input) => {
        const target = await single(ctx, source, input.account);
        const [message, names] = await Promise.all([
          google(ctx, target, `${base}/messages/${encodeURIComponent(input.messageId)}`, { search: { format: "full" } }),
          labelNames(ctx, target),
        ]);
        return full(target, message, names);
      },
    ),
    labels: query(
      {
        description: "List each account's labels with their unread and total counts.",
        input: object({ account }),
      },
      async (ctx: QueryContext, input) =>
        fanOut(await select(ctx, source, input.account), async (target) => {
          const { labels = [] } = await google(ctx, target, `${base}/labels`);
          return mapLimit(labels as { id: string; name: string; type: string }[], 10, async (label) => {
            const detail = await google(ctx, target, `${base}/labels/${encodeURIComponent(label.id)}`);
            return {
              account: target.email,
              id: label.id,
              name: label.name,
              type: label.type,
              unreadThreads: detail.threadsUnread ?? 0,
              threads: detail.threadsTotal ?? 0,
            };
          });
        }).then(({ items, errors }) => ({ labels: items, errors })),
    ),
    send: mutation(
      {
        description: `Send an email, now or later. For a reply, pass replyToMessageId: it stays in the thread, gets a Re: subject and goes to the original sender unless \`to\` is given; replyAll also copies the other recipients. \`from\` must be one of the account's send-as aliases. To send later, pass sendAt: an RFC 3339 time (2026-11-20T09:00:00+01:00), or a local time (2026-11-20T09:00) read in timeZone (an IANA name, default UTC), at most a year ahead. The message is then saved as a draft and sent at that time; see it with scheduled, move it with scheduleDraft and stop it with cancelScheduled. ${attachmentsHelp}`,
        input: object({ ...Compose, sendAt: string().optional(), timeZone: string().optional() }),
        approval: always(),
      },
      async (ctx: MutationContext, input) => {
        const at = input.sendAt === undefined ? undefined : sendTime(input.sendAt, input.timeZone);
        const target = await single(ctx, source, input.account);
        const message = await compose(ctx, target, input);
        if (message.to.length === 0 && message.cc.length === 0 && !input.bcc?.length) throw new Error("Pass at least one recipient.");
        const summary = { to: message.to, cc: message.cc, subject: message.subject, attachments: message.attachments };
        if (at !== undefined) {
          const draft = await deliver(ctx, target, "draft", message.message, message.threadId);
          const to = [...message.to, ...message.cc, ...(input.bcc ?? [])].join(", ");
          return { ...(await scheduleDraft(ctx, target, { id: draft.id, subject: message.subject, to }, at)), ...summary };
        }
        const sent = await deliver(ctx, target, "send", message.message, message.threadId);
        return { account: target.email, messageId: sent.id, threadId: sent.threadId, ...summary };
