// Generated by scripts/google-vendor.ts from shared/google-tools; edit the original and rerun it.
// Basalt's catalog carries edits to this copy (src/catalog/*.patch); re-vendoring must keep them.
// Helpers for the curated tools: choosing accounts, calling Google with one of them, running a read
// across every linked account, and the encodings Gmail and Calendar need.
import { decodeJson, json, object, string, type QueryContext } from "apps";

/** What the helpers use of a query or mutation context. */
export type Base = Pick<QueryContext, "fetch" | "signal" | "cache">;
/** A linked Google account, as any of the Google packages' slots provides it. */
export interface Account {
  readonly id: string;
  readonly fields: { readonly access_token: string };
}

/** How a package reads an account's address with the scopes it already has. */
export type Address = (load: Pick<QueryContext, "fetch" | "signal">, account: Account) => Promise<string>;

/** The accounts a package's curated tools run with, and how it names them. */
export interface Source {
  readonly accounts: readonly Account[];
  readonly address: Address;
  /** Where the package mounts a product's complete API (`gmail` → `api.gmail`), named in the tools' instructions. */
  readonly api: (product: string) => string;
}

const read =
  <T>(url: string, schema: Parameters<typeof decodeJson<T>>[1], pick: (body: T) => string): Address =>
  async ({ fetch, signal }, account) =>
    pick(await decodeJson(await fetch(url, { signal, headers: { Authorization: `Bearer ${account.fields.access_token}` } }), schema));

/** Address lookups for each package's scopes. */
export const addresses = {
  /** Needs the `email` scope; `url` is the userinfo endpoint on a host the provider allows. */
  userinfo: (url: string) => read(url, object({ email: string() }), (body) => body.email),
  gmail: read("https://gmail.googleapis.com/gmail/v1/users/me/profile", object({ emailAddress: string() }), (body) => body.emailAddress),
  /** The primary calendar's ID is the account's address. */
  calendar: read("https://www.googleapis.com/calendar/v3/calendars/primary", object({ id: string() }), (body) => body.id),
  drive: read(
    "https://www.googleapis.com/drive/v3/about?fields=user(emailAddress)",
    object({ user: object({ emailAddress: string() }) }),
    (body) => body.user.emailAddress,
  ),
  /** For scopes that reveal no address, such as Tasks': accounts are named by their ID. */
  id: (async (_load, account) => account.id) as Address,
};

/** One linked account with the address it signs in as. */
export interface Target {
  readonly account: Account;
  readonly email: string;
}

/** The account's address, cached per account so a fan-out costs one request per account at most once a day. */
const emailOf = (ctx: Base, source: Source, account: Account) =>
  ctx.cache.forAccount(account).get({
    key: "email",
    schema: string(),
    freshFor: "1 day",
    load: (load) => source.address(load, account),
  });

/** Every linked account with its address. */
export const linked = (ctx: Base, source: Source): Promise<Target[]> =>
  Promise.all(source.accounts.map(async (account) => ({ account, email: await emailOf(ctx, source, account) })));

/** The accounts a call names: one by address or account ID, or all of them when `account` is omitted. */
export const select = async (ctx: Base, source: Source, account: string | undefined): Promise<Target[]> => {
  const all = await linked(ctx, source);
  if (all.length === 0) throw new Error("No Google account is linked to this app. Connect one first.");
  if (account === undefined) return all;
  const wanted = account.trim().toLowerCase();
  const match = all.filter((target) => target.email.toLowerCase() === wanted || target.account.id === account);
  if (match.length === 0)
    throw new Error(`No linked Google account matches ${account}. Linked accounts: ${all.map((t) => t.email).join(", ")}.`);
  return match;
};

/** The one account a write uses: the named one, or the only linked account. */
export const single = async (ctx: Base, source: Source, account: string | undefined): Promise<Target> => {
  const targets = await select(ctx, source, account);
  if (targets.length > 1)
    throw new Error(`Several Google accounts are linked; pass account as one of: ${targets.map((t) => t.email).join(", ")}.`);
  return targets[0]!;
};

/**
 * Runs a read on each target at once. One account's failure does not hide the others' results: it
 * is reported under `errors` with the account's address.
 */
export const fanOut = async <T>(
  targets: readonly Target[],
  run: (target: Target) => Promise<readonly T[]>,
): Promise<{ readonly items: T[]; readonly errors: { readonly account: string; readonly message: string }[] }> => {
  const settled = await Promise.allSettled(targets.map(run));
  const items: T[] = [];
  const errors: { account: string; message: string }[] = [];
  settled.forEach((result, index) => {
    if (result.status === "fulfilled") items.push(...result.value);
    else errors.push({ account: targets[index]!.email, message: result.reason instanceof Error ? result.reason.message : String(result.reason) });
  });
  return { items, errors };
};

/** Drops undefined fields, which tool results cannot carry: results must be plain JSON. */
export const defined = <T extends object>(value: T): T =>
  Object.fromEntries(Object.entries(value).filter(([, field]) => field !== undefined)) as T;

/** Calls a Google JSON API with the target's token. `search` values left undefined are omitted. */
export const google = async (
  ctx: Base,
  target: Target,
  url: string,
  init: {
    readonly method?: string;
    readonly body?: unknown;
    readonly search?: Readonly<Record<string, string | number | boolean | readonly string[] | undefined>>;
  } = {},
): Promise<any> => {
  const address = new URL(url);
  for (const [key, value] of Object.entries(init.search ?? {})) {
    if (value === undefined) continue;
    for (const item of Array.isArray(value) ? value : [value]) address.searchParams.append(key, String(item));
  }
  const response = await ctx.fetch(address.toString(), {
    method: init.method ?? "GET",
    signal: ctx.signal,
    headers: {
      Authorization: `Bearer ${target.account.fields.access_token}`,
      ...(init.body === undefined ? {} : { "content-type": "application/json" }),
    },
    body: init.body === undefined ? undefined : JSON.stringify(init.body),
  });
  if (response.status === 204) return {};
  return decodeJson(response, json());
};

/** Fetches a body as text, for exports and downloads. */
export const googleText = async (ctx: Base, target: Target, url: string): Promise<string> => {
  const response = await ctx.fetch(url, {
    signal: ctx.signal,
    headers: { Authorization: `Bearer ${target.account.fields.access_token}` },
  });
  if (!response.ok) throw new Error(`Google answered ${response.status}: ${(await response.text()).slice(0, 500)}`);
  return response.text();
};

/** Bounded parallelism, so a 50-thread search does not open 50 connections at once. */
export const mapLimit = async <T, R>(items: readonly T[], limit: number, run: (item: T) => Promise<R>): Promise<R[]> => {
  const results: R[] = new Array(items.length);
  let next = 0;
  const worker = async () => {
    while (next < items.length) {
      const index = next++;
      results[index] = await run(items[index]!);
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
};

const bytesToBinary = (bytes: Uint8Array) => {
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return binary;
};

/** UTF-8 text as base64url, the encoding Gmail's `raw` field takes. */
export const base64url = (text: string) =>
  btoa(bytesToBinary(new TextEncoder().encode(text))).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");

/** Base64 for a MIME body, wrapped at 76 characters. */
export const base64Lines = (text: string) => btoa(bytesToBinary(new TextEncoder().encode(text))).replace(/.{76}/g, "$&\r\n");

/** Decodes a Gmail body part (base64url bytes) in the part's charset. */
export const decodeBody = (data: string, charset = "utf-8") => {
  const binary = atob(data.replaceAll("-", "+").replaceAll("_", "/"));
  const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
  try {
    return new TextDecoder(charset).decode(bytes);
  } catch {
    return new TextDecoder("utf-8").decode(bytes);
  }
};

const entities: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };

/** Readable text from an HTML body: block elements become line breaks, tags and scripts go. */
export const htmlToText = (html: string) =>
  html
    .replace(/<(script|style|head)[\s\S]*?<\/\1>/gi, "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(p|div|tr|li|h[1-6]|blockquote)>/gi, "\n")
    .replace(/<li[^>]*>/gi, "- ")
    .replace(/<a\s[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/gi, (_, href: string, text: string) =>
      text.trim() && !href.startsWith("mailto:") && text.trim() !== href ? `${text} (${href})` : text,
    )
    .replace(/<[^>]+>/g, "")
    .replace(/&(#x?[0-9a-f]+|\w+);/gi, (match, code: string) => {
      if (code.startsWith("#x") || code.startsWith("#X")) return String.fromCodePoint(parseInt(code.slice(2), 16));
      if (code.startsWith("#")) return String.fromCodePoint(parseInt(code.slice(1), 10));
      return entities[code.toLowerCase()] ?? match;
    })
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

/** A header value with non-ASCII text as an RFC 2047 encoded word. */
export const encodeHeader = (value: string) =>
  /^[\x20-\x7e]*$/.test(value) ? value : `=?UTF-8?B?${btoa(bytesToBinary(new TextEncoder().encode(value)))}?=`;

/** Milliseconds a zone is ahead of UTC at an instant. */
const zoneOffset = (zone: string, instant: number) => {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-US", {
      timeZone: zone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    })
      .formatToParts(new Date(instant))
      .map((part) => [part.type, part.value]),
  );
  const asUtc = Date.UTC(+parts.year!, +parts.month! - 1, +parts.day!, +parts.hour!, +parts.minute!, +parts.second!);
  return asUtc - Math.floor(instant / 1000) * 1000;
};

/** The instant a wall-clock time in a zone names. */
export const zonedTime = (zone: string, year: number, month: number, day: number, hour = 0, minute = 0) => {
  const guess = Date.UTC(year, month - 1, day, hour, minute);
  const first = guess - zoneOffset(zone, guess);
  return first - (zoneOffset(zone, first) - zoneOffset(zone, guess));
};

/** The calendar date (year, month, day) of an instant in a zone. */
export const zonedDate = (zone: string, instant: number) => {
  const [year, month, day] = new Intl.DateTimeFormat("en-CA", { timeZone: zone, year: "numeric", month: "2-digit", day: "2-digit" })
    .format(new Date(instant))
    .split("-")
    .map(Number) as [number, number, number];
  return { year, month, day };
};

/**
 * An instant from what a model is likely to pass: an RFC 3339 time, a date (midnight in `zone`),
 * "now", "today", "tomorrow" or "yesterday".
 */
export const parseTime = (value: string, zone: string, now = Date.now()) => {
  const text = value.trim().toLowerCase();
  if (text === "now") return now;
  const shift = { yesterday: -1, today: 0, tomorrow: 1 }[text];
  if (shift !== undefined) {
    const today = zonedDate(zone, now);
    return zonedTime(zone, today.year, today.month, today.day + shift);
  }
  const date = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (date) return zonedTime(zone, +date[1]!, +date[2]!, +date[3]!);
  const local = /^(\d{4})-(\d{2})-(\d{2})t(\d{2}):(\d{2})(?::\d{2}(?:\.\d+)?)?$/.exec(text);
  if (local) return zonedTime(zone, +local[1]!, +local[2]!, +local[3]!, +local[4]!, +local[5]!);
  const instant = Date.parse(value);
  if (Number.isNaN(instant))
    throw new Error(`Could not read the time "${value}". Use RFC 3339 (2026-10-14T09:00:00-07:00), a date (2026-10-14), "now", "today" or "tomorrow".`);
  return instant;
};

const TimeZone = object({ value: string() });

/** The zone of the account's Calendar settings, which dates without an offset are read in. */
export const calendarZone = async (ctx: Base, target: Target) =>
  ctx.cache.forAccount(target.account).get({
    key: "calendar-zone",
    schema: string(),
    freshFor: "1 day",
    load: async ({ fetch, signal }) => {
      const response = await fetch("https://www.googleapis.com/calendar/v3/users/me/settings/timezone", {
        signal,
        headers: { Authorization: `Bearer ${target.account.fields.access_token}` },
      });
      return (await decodeJson(response, TimeZone)).value;
    },
  });

-- One row per scheduled send, so people and agents can list what waits. The run is the schedule;
-- its status says whether it is waiting, sent, failed or cancelled.
CREATE TABLE scheduled_sends (
  run_id TEXT PRIMARY KEY NOT NULL,
  account_id TEXT NOT NULL,
  account TEXT NOT NULL,
  draft_id TEXT NOT NULL,
  send_at INTEGER NOT NULL,
  subject TEXT NOT NULL,
  recipients TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE INDEX scheduled_sends_draft ON scheduled_sends (account_id, draft_id);
CREATE INDEX scheduled_sends_time ON scheduled_sends (account_id, send_at);

// Attachments and delivery for Gmail writes. Files come inline, from a link or from another
// message; the message is a multipart/mixed RFC 2822 document built straight into bytes, sent as
// JSON `raw` while small and by Gmail's resumable upload above that.
import { array, decodeJson, json, object, string } from "apps";
import { encodeHeader, google, type Base, type Target } from "./shared.js";

const base = "https://gmail.googleapis.com/gmail/v1/users/me";
const upload = "https://gmail.googleapis.com/upload/gmail/v1/users/me";

/** Gmail refuses mail whose attachments add up to more than 25 MB. */
export const attachmentLimit = 25 * 1024 * 1024;
/** Google documents its JSON and simple-upload paths for 5 MB or less; larger messages are uploaded resumably. */
export const uploadThreshold = 5 * 1024 * 1024;

export const Attachment = object({
  filename: string().optional(),
  mimeType: string().optional(),
  contentBase64: string().optional(),
  url: string().optional(),
  messageId: string().optional(),
  attachmentId: string().optional(),
});
export const Attachments = array(Attachment).optional();

export type AttachmentInput = {
  readonly filename?: string;
  readonly mimeType?: string;
  readonly contentBase64?: string;
  readonly url?: string;
  readonly messageId?: string;
  readonly attachmentId?: string;
};

export const attachmentsHelp =
  "attachments: files to attach, each from exactly one source: `contentBase64` (the file's bytes as base64, such as an uploaded file or one the agent has open; needs `filename`), `url` (an https link the file downloads from without signing in; nothing but the request is sent to it) or `messageId` with `attachmentId` (an attachment of another message, as readMessage lists it). `filename` and `mimeType` are read from the source when left out. Together the files may total 25 MB, Gmail's limit; pass files over a few MB by `url`, since inline content travels inside the tool call.";

interface File {
  readonly filename: string;
  readonly mimeType: string;
  readonly bytes: Uint8Array;
}

const types: Record<string, string> = {
  pdf: "application/pdf",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  svg: "image/svg+xml",
  txt: "text/plain",
  md: "text/markdown",
  csv: "text/csv",
  html: "text/html",
  json: "application/json",
  ics: "text/calendar",
  zip: "application/zip",
  doc: "application/msword",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  xls: "application/vnd.ms-excel",
  xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  ppt: "application/vnd.ms-powerpoint",
  pptx: "application/vnd.openxmlformats-officedocument.presentationml.presentation",
  mp3: "audio/mpeg",
  mp4: "video/mp4",
  mov: "video/quicktime",
};
const generic = "application/octet-stream";
const guess = (filename: string) => types[/\.([a-z0-9]+)$/i.exec(filename)?.[1]?.toLowerCase() ?? ""] ?? generic;
/** A MIME type that cannot break the part's headers, else the generic one. */
const mimeType = (value: string | undefined) => {
  const type = value?.split(";")[0]?.trim().toLowerCase();
  return type && /^[a-z0-9!#$&^_.+-]+\/[a-z0-9!#$&^_.+-]+$/.test(type) ? type : undefined;
};
/** A file name without line breaks, quotes or path separators, so it stays one header parameter. */
const filename = (value: string) => value.replace(/[\r\n"\\/]+/g, " ").trim().slice(0, 255) || "attachment";

const tooBig = () =>
  new Error(`Attachments add up to more than 25 MB, Gmail's limit. Share a link to large files in the body instead.`);

const decodeBase64 = (value: string) => {
  const text = value.replace(/^data:[^,]*;base64,/i, "").replace(/\s+/g, "").replaceAll("-", "+").replaceAll("_", "/");
  let binary: string;
  try {
    binary = atob(text);
  } catch {
    throw new Error("contentBase64 is not valid base64.");
  }
  return Uint8Array.from(binary, (char) => char.charCodeAt(0));
};

const decoded = (value: string) => {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
};

/** Reads a link's body, stopping as soon as it passes the remaining budget. */
const download = async (ctx: Base, url: URL, remaining: number) => {
  // No credentials go with the request: the link alone must grant the file.
  const response = await ctx.fetch(url.toString(), { signal: ctx.signal, redirect: "follow" });
  if (!response.ok) throw new Error(`Downloading ${url.hostname} answered ${response.status}.`);
  if (response.redirected && new URL(response.url).protocol !== "https:") throw new Error(`${url.hostname} redirected the download away from https.`);
  if (Number(response.headers.get("content-length") ?? 0) > remaining) throw tooBig();
  const chunks: Uint8Array[] = [];
  let size = 0;
  const reader = response.body?.getReader();
  for (;;) {
    const next = await reader?.read();
    if (!next || next.done) break;
    size += next.value.byteLength;
    if (size > remaining) {
      await reader?.cancel();
      throw tooBig();
    }
    chunks.push(next.value);
  }
  const bytes = new Uint8Array(size);
  let at = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, at);
    at += chunk.byteLength;
  }
  // Only `filename*` and URL paths are percent-encoded; a plain `filename="50% off.pdf"` is literal.
  const disposition = response.headers.get("content-disposition") ?? "";
  const extended = /filename\*\s*=\s*UTF-8''([^;]+)/i.exec(disposition)?.[1];
  const plain = /filename\s*=\s*"?([^";]+)"?/i.exec(disposition)?.[1];
  const named = extended ? decoded(extended) : (plain ?? decoded(url.pathname.split("/").at(-1) ?? ""));
  const served = mimeType(response.headers.get("content-type") ?? undefined);
  return { bytes, filename: named, mimeType: served === generic ? undefined : served };
};

interface Part {
  readonly filename?: string;
  readonly mimeType?: string;
  readonly body?: { readonly attachmentId?: string };
  readonly parts?: readonly Part[];
}
const findPart = (part: Part | undefined, id: string): Part | undefined =>
  part?.body?.attachmentId === id ? part : (part?.parts ?? []).map((child) => findPart(child, id)).find(Boolean);

const resolve = async (ctx: Base, target: Target, input: AttachmentInput, remaining: number): Promise<File> => {
  const sources = [input.contentBase64 !== undefined, input.url !== undefined, input.messageId !== undefined || input.attachmentId !== undefined];
  if (sources.filter(Boolean).length !== 1)
    throw new Error("Give each attachment exactly one source: contentBase64, url, or messageId with attachmentId.");
  if (input.contentBase64 !== undefined) {
    if (!input.filename) throw new Error("An attachment given as contentBase64 needs a filename.");
    const bytes = decodeBase64(input.contentBase64);
    if (bytes.byteLength > remaining) throw tooBig();
    const declared = /^data:([^;,]+)/i.exec(input.contentBase64)?.[1];
    return { bytes, filename: filename(input.filename), mimeType: mimeType(input.mimeType) ?? mimeType(declared) ?? guess(input.filename) };
  }
  if (input.url !== undefined) {
    const url = URL.parse(input.url);
    if (url === null || url.protocol !== "https:") throw new Error(`Attachment links must be https URLs: ${input.url}`);
    const file = await download(ctx, url, remaining);
    const name = filename(input.filename ?? file.filename);
    return { bytes: file.bytes, filename: name, mimeType: mimeType(input.mimeType) ?? file.mimeType ?? guess(name) };
  }
  if (!input.messageId || !input.attachmentId) throw new Error("An attachment from another message needs both messageId and attachmentId.");
  const message = encodeURIComponent(input.messageId);
  const [{ data = "" }, original] = await Promise.all([
    google(ctx, target, `${base}/messages/${message}/attachments/${encodeURIComponent(input.attachmentId)}`),
    google(ctx, target, `${base}/messages/${message}`, { search: { format: "full" } }),
  ]);
  const bytes = decodeBase64(data);
  if (bytes.byteLength > remaining) throw tooBig();
  // Gmail can renumber attachment ids between reads; the caller's filename then names the file.
  const part = findPart(original.payload, input.attachmentId);
  const name = filename(input.filename ?? part?.filename ?? "attachment");
  return { bytes, filename: name, mimeType: mimeType(input.mimeType) ?? mimeType(part?.mimeType) ?? guess(name) };
};

/** Every attachment's bytes, in order, within Gmail's 25 MB. */
export const resolveAttachments = async (ctx: Base, target: Target, inputs: readonly AttachmentInput[] = []) => {
  const files: File[] = [];
  let total = 0;
  for (const input of inputs) {
    const file = await resolve(ctx, target, input, attachmentLimit - total);
    total += file.bytes.byteLength;
    files.push(file);
  }
  return files;
};

const alphabet = new TextEncoder().encode("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/");
const crlf = [13, 10];
/** Base64 in 76-character lines, each ending in CRLF. */
const base64Length = (size: number) => {
  const chars = Math.ceil(size / 3) * 4;
  return chars + Math.ceil(chars / 76) * 2;
};
const writeBase64 = (bytes: Uint8Array, out: Uint8Array, start: number) => {
  let at = start;
  let column = 0;
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i]!;
    const b = bytes[i + 1];
    const c = bytes[i + 2];
    out[at++] = alphabet[a >> 2]!;
    out[at++] = alphabet[((a & 3) << 4) | ((b ?? 0) >> 4)]!;
    out[at++] = b === undefined ? 61 : alphabet[((b & 15) << 2) | ((c ?? 0) >> 6)]!;
    out[at++] = c === undefined ? 61 : alphabet[c & 63]!;
    column += 4;
    if (column === 76) {
      out.set(crlf, at);
      at += 2;
      column = 0;
    }
  }
  if (column > 0) {
    out.set(crlf, at);
    at += 2;
  }
  return at;
};

/**
 * The RFC 2822 message: `headers`, then the body alone, or with files a multipart/mixed whose
 * first part is the body. The bytes are built once, so a 25 MB attachment is never copied as text.
 */
export const encodeMessage = (headers: readonly string[], body: string, html: boolean, files: readonly File[]) => {
  const text = new TextEncoder();
  const bodyType = `Content-Type: ${html ? "text/html" : "text/plain"}; charset="UTF-8"\r\nContent-Transfer-Encoding: base64\r\n`;
  const boundary = `basalt-${crypto.randomUUID()}`;
  const head = text.encode(
    [...headers, "MIME-Version: 1.0", ...(files.length ? [`Content-Type: multipart/mixed; boundary="${boundary}"`, "", `--${boundary}`] : [])].join("\r\n") +
      "\r\n" +
      bodyType +
      "\r\n",
  );
  const bodyBytes = text.encode(body);
  const parts = files.map((file) => {
    const name = encodeHeader(file.filename);
    return text.encode(
      `--${boundary}\r\nContent-Type: ${file.mimeType}; name="${name}"\r\nContent-Disposition: attachment; filename="${name}"\r\nContent-Transfer-Encoding: base64\r\n\r\n`,
    );
  });
  const close = text.encode(files.length ? `--${boundary}--\r\n` : "");
  const size =
    head.length + base64Length(bodyBytes.length) + parts.reduce((sum, part, i) => sum + part.length + base64Length(files[i]!.bytes.length), 0) + close.length;
  const out = new Uint8Array(size);
  out.set(head, 0);
  let at = writeBase64(bodyBytes, out, head.length);
  parts.forEach((part, i) => {
    out.set(part, at);
    at = writeBase64(files[i]!.bytes, out, at + part.length);
  });
  out.set(close, at);
  return out;
};

const base64url = (bytes: Uint8Array) => {
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
};

/** What Gmail answers for a sent message (`id` is the message) or a saved draft (`id` is the draft). */
export interface Delivered {
  readonly id: string;
  readonly threadId?: string;
  readonly message?: { readonly id?: string; readonly threadId?: string };
}
const delivered = (value: unknown): Delivered => {
  if (typeof (value as { id?: unknown } | null)?.id !== "string") throw new Error("Gmail answered without an id.");
  return value as Delivered;
};

/**
 * Sends a message or saves a draft. Up to 5 MB the message goes as JSON `raw`; above that by
 * Gmail's resumable upload, which also carries the thread, since a simple upload cannot.
 */
export const deliver = async (
  ctx: Base,
  target: Target,
  kind: "send" | "draft",
  message: Uint8Array<ArrayBuffer>,
  threadId: string | undefined,
): Promise<Delivered> => {
  const thread = threadId ? { threadId } : {};
  if (message.length <= uploadThreshold) {
    const raw = { raw: base64url(message), ...thread };
    return delivered(
      kind === "send"
        ? await google(ctx, target, `${base}/messages/send`, { method: "POST", body: raw })
        : await google(ctx, target, `${base}/drafts`, { method: "POST", body: { message: raw } }),
    );
  }
  const authorization = `Bearer ${target.account.fields.access_token}`;
  const start = await ctx.fetch(`${upload}/${kind === "send" ? "messages/send" : "drafts"}?uploadType=resumable`, {
    method: "POST",
    signal: ctx.signal,
    headers: {
      Authorization: authorization,
      "content-type": "application/json; charset=UTF-8",
      "X-Upload-Content-Type": "message/rfc822",
      "X-Upload-Content-Length": String(message.length),
    },
    body: JSON.stringify(kind === "send" ? thread : { message: thread }),
  });
  const location = start.headers.get("location");
  if (!start.ok || !location) throw new Error(`Gmail did not start the upload (${start.status}): ${(await start.text()).slice(0, 300)}`);
  const session = new URL(location, upload);
  // The session URL's upload id authorises the bytes; the account's credential goes only to Gmail.
  const own = session.origin === new URL(upload).origin;
  const response = await ctx.fetch(session.toString(), {
    method: "PUT",
    signal: ctx.signal,
    headers: { ...(own ? { Authorization: authorization } : {}), "content-type": "message/rfc822" },
    body: message,
  });
  return delivered(await decodeJson(response, json()));
};

// Scheduled send. Gmail's API has no send-later (it is a Gmail web feature), so a scheduled
// message is a saved draft that the `sendLater` workflow sends at its time, from the account that
// scheduled it. The workflow is the behaviour a person can open and edit; `scheduled` lists what
// waits and `cancelScheduled` stops it, leaving the draft where it was.
import {
  NonRetryableError,
  boolean,
  mutation,
  number,
  object,
  query,
  string,
  workflow,
  type AppRequirements,
  type MutationContext,
  type QueryContext,
  type WorkflowContext,
  type WorkflowReads,
  type WorkflowStepContext,
} from "apps";
import { always } from "apps/operations/approval";
import { google, mapLimit, parseTime, select, single, type Account, type Source, type Target } from "./shared.js";

const base = "https://gmail.googleapis.com/gmail/v1/users/me";
const account = string().optional();
const day = 86_400_000;

export const sendLaterName = "sendLater";

/** The workflow, for a package whose linked Google accounts `accounts` reads from a step. */
export const sendLater = <Requirements extends AppRequirements>(
  accounts: (step: WorkflowStepContext<Requirements>) => readonly Account[],
) =>
  workflow(
    {
      description:
        "Sends a scheduled Gmail draft at its time from the account that scheduled it. A draft already sent or deleted by hand ends the run quietly; if Gmail refuses the send, the person is asked in Human in the loop whether to send it again or keep it as a draft.",
      input: object({
        accountId: string({ minLength: 1 }),
        draftId: string({ minLength: 1 }),
        sendAt: number(),
        subject: string(),
        to: string(),
      }),
    },
    async (ctx: WorkflowContext<Requirements>, input) => {
      await ctx.step.sleepUntil("wait for the send time", input.sendAt);
      const send = (name: string) =>
        ctx.step.do(name, { retries: { limit: 3, delay: "1 minute", backoff: "exponential" }, timeout: "2 minutes" }, async (step) => {
          const linked = accounts(step).find((candidate) => candidate.id === input.accountId);
          if (!linked) throw new NonRetryableError("The Gmail account that scheduled this email is no longer linked to the app.");
          const response = await step.fetch(`${base}/drafts/send`, {
            method: "POST",
            signal: step.signal,
            headers: { Authorization: `Bearer ${linked.fields.access_token}`, "content-type": "application/json" },
            body: JSON.stringify({ id: input.draftId }),
          });
          // Sent or deleted by hand before its time: nothing is left to send.
          if (response.status === 404) return { outcome: "gone" };
          const text = await response.text();
          const failure = `Gmail answered ${response.status}: ${text.slice(0, 300)}`;
          if (response.status === 429 || response.status >= 500) throw new Error(failure);
          if (!response.ok) throw new NonRetryableError(failure);
          const sent = JSON.parse(text) as { id?: string; threadId?: string };
          return { outcome: "sent", messageId: sent.id ?? "", threadId: sent.threadId ?? "" };
        });
      try {
        return await send("send the draft");
      } catch (error) {
        const reason = error instanceof Error ? error.message : String(error);
        const question = await ctx.step.requestInput("ask what to do with the unsent email", {
          timeoutMs: 7 * day,
          display: { kind: "choice" },
          form: {
            mode: "form",
            message: `Your scheduled email "${input.subject}" to ${input.to} was not sent: ${reason}. It is still in your Gmail drafts.`,
            requestedSchema: {
              type: "object",
              properties: { choice: { type: "string", title: "What should happen?", enum: ["Send it now", "Keep it as a draft"] } },
              required: ["choice"],
            },
          },
        });
        const answer = await ctx.step.waitForInput("wait for the person's answer", question);
        if (answer.status === "expired") return { outcome: "kept" };
        if (answer.status === "answered" && answer.response.action === "accept" && answer.response.content?.choice === "Send it now")
          return send("send the draft again");
        return { outcome: "kept" };
      }
    },
  );

/** A time a person or model is likely to give, checked: not past, at most a year away. */
export const sendTime = (sendAt: string, timeZone: string | undefined, now = Date.now()) => {
  const zone = timeZone ?? "UTC";
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: zone });
  } catch {
    throw new Error(`Unknown time zone ${zone}. Use an IANA name such as Europe/Zurich.`);
  }
  const at = parseTime(sendAt, zone, now);
  if (at < now - 60_000) throw new Error(`${sendAt} has already passed. Use send without sendAt to send it now.`);
  if (at > now + 365 * day) throw new Error("A message can be scheduled at most a year ahead.");
  return Math.max(at, now);
};

type WorkflowRun = Awaited<ReturnType<WorkflowReads["get"]>>;

const active = new Set<WorkflowRun["status"]>(["queued", "running", "waiting", "paused", "waitingForPause"]);

type Row = { run_id: string; account: string; draft_id: string; send_at: number; subject: string; recipients: string };

/** Ends the draft's waiting schedules; returns how many there were. */
const cancelDraft = async (ctx: MutationContext, target: Target, draftId: string) => {
  const rows = ctx.sql
    .exec<Pick<Row, "run_id">>("SELECT run_id FROM scheduled_sends WHERE account_id = ? AND draft_id = ?", target.account.id, draftId)
    .toArray();
  let cancelled = 0;
  for (const row of rows) {
    // A run the host no longer knows is not waiting either.
    const run = await ctx.workflows.get({ run: row.run_id }).catch(() => undefined);
    if (run === undefined || !active.has(run.status)) continue;
    await ctx.workflows.terminate({ run: row.run_id });
    cancelled++;
  }
  return cancelled;
};

/** Schedules a saved draft, replacing its earlier schedule, and records it for `scheduled`. */
export const scheduleDraft = async (
  ctx: MutationContext,
  target: Target,
  draft: { readonly id: string; readonly subject: string; readonly to: string },
  sendAt: number,
) => {
  const replaced = await cancelDraft(ctx, target, draft.id);
  const run = await ctx.workflows.start({
    workflow: sendLaterName,
    input: { accountId: target.account.id, draftId: draft.id, sendAt, subject: draft.subject, to: draft.to },
  });
  try {
    ctx.sql.exec(
      "INSERT INTO scheduled_sends (run_id, account_id, account, draft_id, send_at, subject, recipients, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
      run.id,
      target.account.id,
      target.email,
      draft.id,
      sendAt,
      draft.subject,
      draft.to,
      Date.now(),
    );
  } catch (error) {
    // An unrecorded run could be neither listed nor cancelled, so it must not wait.
    await ctx.workflows.terminate({ run: run.id });
    throw error;
  }
  return { account: target.email, draftId: draft.id, runId: run.id, sendAt: new Date(sendAt).toISOString(), replacedSchedules: replaced };
};

const outcomes: Record<string, string> = { sent: "sent", gone: "draft gone", kept: "kept as draft" };
const state = (run: WorkflowRun | undefined, sendAt: number) => {
  if (run === undefined) return "unknown";
  if (run.status === "terminated") return "cancelled";
  if (run.status === "errored") return "failed";
  if (run.status === "complete") return outcomes[(run.output as { outcome?: string } | null)?.outcome ?? ""] ?? "unknown";
  if (sendAt > Date.now()) return "scheduled";
  // Past its time a run waits only on the person's answer about a refused send.
  return run.status === "waiting" ? "needs you" : "sending";
};

interface DraftHeader {
  readonly message?: { readonly payload?: { readonly headers?: readonly { readonly name: string; readonly value: string }[] } };
}
const draftHeader = (draft: DraftHeader, name: string) =>
  draft.message?.payload?.headers?.find((h) => h.name.toLowerCase() === name.toLowerCase())?.value ?? "";

/** The scheduling tools; `send` also schedules when given `sendAt`. */
export const scheduleTools = (source: Source) => ({
  scheduleDraft: mutation(
    {
      description:
        "Schedule a saved draft to be sent later, or move an already scheduled draft to a new time. sendAt is an RFC 3339 time (2026-11-20T09:00:00+01:00), or a local time (2026-11-20T09:00) read in timeZone (an IANA name, default UTC), at most a year ahead. The draft stays in Gmail's Drafts until then and is sent as it reads at that time, so edits made in Gmail go out too. Gmail's own Scheduled folder is not used: its API cannot schedule.",
      input: object({ account, draftId: string({ minLength: 1 }), sendAt: string({ minLength: 1 }), timeZone: string().optional() }),
      approval: always(),
    },
    async (ctx: MutationContext, input) => {
      const at = sendTime(input.sendAt, input.timeZone);
      const target = await single(ctx, source, input.account);
      const draft: DraftHeader = await google(ctx, target, `${base}/drafts/${encodeURIComponent(input.draftId)}`, {
        search: { format: "metadata", metadataHeaders: ["To", "Cc", "Bcc", "Subject"] },
      });
      const to = ["To", "Cc", "Bcc"].map((name) => draftHeader(draft, name)).filter(Boolean).join(", ");
      if (!to) throw new Error("That draft has no recipients yet. Add them before scheduling it.");
      return scheduleDraft(ctx, target, { id: input.draftId, subject: draftHeader(draft, "Subject"), to }, at);
    },
  ),
  scheduled: query(
    {
      description:
        "List scheduled emails, soonest first: each with its account, draft, recipients and subject as scheduled, send time and state: scheduled, sending, needs you (Gmail refused it and Human in the loop asks what to do), sent, draft gone (sent or deleted by hand first), kept as draft (after a refusal), failed or cancelled. Shows only scheduled, sending and needs-you ones unless `all` is true.",
      input: object({ account, all: boolean().optional() }),
    },
    async (ctx: QueryContext, input) => {
      const ids = (await select(ctx, source, input.account)).map((target) => target.account.id);
      const rows = ctx.sql
        .exec<Row>(
          `SELECT run_id, account, draft_id, send_at, subject, recipients FROM scheduled_sends WHERE account_id IN (${ids.map(() => "?").join(", ")}) ORDER BY send_at DESC LIMIT 100`,
          ...ids,
        )
        .toArray();
      const listed = await mapLimit(rows, 10, async (row) => {
        const run = await ctx.workflows.get({ run: row.run_id }).catch(() => undefined);
        return {
          account: row.account,
          draftId: row.draft_id,
          runId: row.run_id,
          to: row.recipients,
          subject: row.subject,
          sendAt: new Date(row.send_at).toISOString(),
          state: state(run, row.send_at),
        };
      });
      const shown = input.all ? listed : listed.filter((item) => ["scheduled", "sending", "needs you"].includes(item.state));
      return { scheduled: shown.sort((a, b) => a.sendAt.localeCompare(b.sendAt)) };
    },
  ),
  cancelScheduled: mutation(
    {
      description: "Cancel a scheduled email. It is not sent, and its draft stays in Gmail's Drafts to edit, schedule again or send.",
      input: object({ account, draftId: string({ minLength: 1 }) }),
      approval: always(),
    },
    async (ctx: MutationContext, input) => {
      const target = await single(ctx, source, input.account);
      const cancelled = await cancelDraft(ctx, target, input.draftId);
      if (cancelled === 0) throw new Error("No scheduled send of that draft is waiting. List them with scheduled.");
      return { account: target.email, draftId: input.draftId, cancelled, draft: "kept in Drafts" };
    },
  ),
});
